component.css:
.mld {--ink: #2a3440;--dim: #6b7480;--panel: #f8f0de;--acc: #2d5680;position: relative;width: 100%;aspect-ratio: 1672 / 941;container-type: size;overflow: hidden;border-radius: 10px;background: #0d1420;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.mld *, .mld *::before, .mld *::after { box-sizing: border-box; }
.mld button { font-family: inherit; border: 0; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; text-align: left; }
.mld button:focus { outline: none; }
.mld button:focus-visible { outline: 2px solid #4e86b4; outline-offset: 1px; }
.mld-bg { position: absolute; inset: 0; background: url("https://origin.picgo.net/2026/10/11/100008601956a9163bf72203e4.png") center / 100% 100% no-repeat; pointer-events: none; }
.mld-slots, .mld-pager { position: absolute; inset: 0; }
.mld-slot {position: absolute; width: 22.7%; height: 22.7%;border-radius: 6px;overflow: hidden;transition: box-shadow .15s;}
@media (hover: hover) {.mld-slot:not(.is-empty):hover { box-shadow: inset 0 0 0 2px #2d56809c; }}
.mld-slot__in {position: absolute; inset: 7% 8% 6%;display: flex; flex-direction: column; justify-content: space-between;color: var(--ink);}
.mld-slot__top { display: flex; align-items: baseline; gap: 2%; font-size: 1.55cqh; color: var(--dim); }
.mld-slot__top b { font-size: 1.9cqh; color: var(--acc); letter-spacing: .05em; }
.mld-slot__loc {font-size: 2.35cqh; font-weight: 700; color: var(--ink);letter-spacing: .04em;overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
.mld-slot__sub { display: flex; align-items: baseline; gap: 5%; font-size: 1.5cqh; color: var(--dim); }
.mld-slot__sub b { color: #8a5a28; font-weight: 700; }
.mld-slot__scene {font-size: 1.45cqh; line-height: 1.4; color: #4d5661;display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;}
.mld-slot.is-empty { cursor: default; }
.mld-pager__btn {position: absolute; top: 80%; height: 10%; display: flex; align-items: center; justify-content: center;font-size: 2.6cqh; color: var(--ink); border-radius: 4px;}
.mld-pager__btn--num { width: 6.5%; }
.mld-pager__btn--num.is-cur { color: var(--acc); font-weight: 800; text-decoration: underline; text-underline-offset: .5cqh; }
@media (hover: hover) {.mld-pager__btn:hover { background: #2d568024; }}
#mldBack { position: absolute; left: 1.5%; top: 91.8%; width: 11.5%; height: 5.5%; border-radius: 6px; }
@media (hover: hover) {#mldBack:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}

component.script:
"use strict";(() => {
var D = String.fromCharCode(36);
var SL = String.fromCharCode(47);
var Z = n => "<" + D + n + D + ">";
var ZE = n => "<" + SL + D + n + D + ">";
var et = (tag, inner) => "<" + tag + ">" + inner + "<" + SL + tag + ">";
var root = document.getElementById("mldRoot");
if (!root) return;
var byId = i => document.getElementById(i);
var el = (tag, cls) => {
  var e = document.createElement(tag);
  if (cls) e.className = cls;
  return e;
};
var COLS = [21, 45.3, 69.6];
var ROWS = [25.6, 51.2];
var ROUTES = { A: "A线·秦瑾", B: "B线·林戌岚", C: "C线·乌尔里克" };
var slotKey = n => "都档" + n;
var cgCount = s => {
  var n = 0;
  for (var i = 0; i + 1 < (s || "").length; i += 2) {
    var a = s.charAt(i), b = s.charAt(i + 1);
    if (a >= "A" && a <= "C" && b >= "1" && b <= "8") n++;
  }
  return n;
};
var bridge = typeof readFromLocal === "function";
var readSlot = n => {
  if (bridge) return Promise.resolve(readFromLocal(slotKey(n))).catch(() => "");
  try { return Promise.resolve(localStorage.getItem(slotKey(n)) || ""); } catch (e) { return Promise.resolve(""); }
};
var parse = v => { var p = (v || "").split("|"); return p.length === 11 ? p : null; };
var page = 0;
var equip = (pg, idx, d) => {
  var txt =
    "【读档 · 存档 " + (pg + 1) + "-" + (idx + 1) + "】" + (ROUTES[d[0]] || d[0]) +
    "\n日期：" + d[1] + " " + d[2] + "　地点：" + d[3] +
    "\n好感：龙" + d[4] + " 虎" + d[5] + " 狼" + d[6] + "　渴" + d[7] + " 饿" + d[8] +
    "\n本局已触发CG：" + (d[9] || "无") +
    "\n断点剧情：" + d[10] +
    "\n请严格按以上状态恢复故事，从断点接着推进（一次只推进一个场景，按组件协议输出）。";
  try { fillInput(txt); } catch (e) {}
  toast("存档已装入输入框 —— 发送以继续");
};
var render = () => {
  var box = byId("mldSlots");
  box.innerHTML = "";
  for (var i = 0; i < 6; i++) {
    (function (idx) {
      var slotNo = page * 6 + idx + 1;
      var cell = el("button", "mld-slot");
      cell.style.left = COLS[idx % 3] + "%";
      cell.style.top = ROWS[idx < 3 ? 0 : 1] + "%";
      cell.setAttribute("aria-label", "读档-" + slotNo);
      box.appendChild(cell);
      readSlot(slotNo).then(v => {
        var d = parse(v);
        if (!d) {
          cell.className += " is-empty";
          cell.addEventListener("click", () => { toast("这个位置没有存档。"); });
          return;
        }
        var inEl = el("div", "mld-slot__in");
        var top = el("div", "mld-slot__top");
        var bTop = el("b");
        bTop.textContent = ROUTES[d[0]] || d[0];
        var spTop = el("span");
        spTop.textContent = d[1] + " " + d[2];
        top.appendChild(bTop);
        top.appendChild(spTop);
        var loc = el("div", "mld-slot__loc");
        loc.textContent = d[3];
        var sub = el("div", "mld-slot__sub");
        var spA = el("span");
        spA.textContent = "好感 ";
        var bA = el("b");
        bA.textContent = d[4] !== "-" && d[4] !== "" ? d[4] : (d[5] !== "-" && d[5] !== "" ? d[5] : d[6]);
        spA.appendChild(bA);
        var spB = el("span");
        spB.textContent = "渴" + d[7] + " 饿" + d[8];
        var spC = el("span");
        spC.textContent = "CG×" + cgCount(d[9]);
        sub.appendChild(spA);
        sub.appendChild(spB);
        sub.appendChild(spC);
        var scene = el("div", "mld-slot__scene");
        scene.textContent = d[10];
        inEl.appendChild(top);
        inEl.appendChild(loc);
        inEl.appendChild(sub);
        inEl.appendChild(scene);
        cell.appendChild(inEl);
        cell.addEventListener("click", () => { equip(page, idx, d); });
      });
    })(i);
  }
  var pager = byId("mldPager");
  pager.innerHTML = "";
  var mk = (txt, cls, fn) => {
    var b = document.createElement("button");
    b.className = "mld-pager__btn " + cls;
    b.textContent = txt;
    b.addEventListener("click", fn);
    pager.appendChild(b);
  };
  mk("‹", "", () => { page = (page + 2) % 3; render(); });
  for (var n = 0; n < 3; n++) (function (num) {
    mk(String(num + 1), "mld-pager__btn--num" + (num === page ? " is-cur" : ""), () => { page = num; render(); });
  })(n);
  mk("›", "", () => { page = (page + 1) % 3; render(); });
  var pos = [43.5, 46.8, 51.3, 55.8, 59.3];
  var kids = pager.children;
  for (var j = 0; j < kids.length; j++) kids[j].style.left = pos[j] + "%";
};
render();
byId("mldBack").addEventListener("click", () => {
  changeMsg("" + Z("大都会标题页") + et("页面", "标题") + et("动画", "完成") + et("状态", "") + ZE("大都会标题页"));
});
})();
